#include <stdio.h>

void increment(int x) {
    x = x + 1;
}

int main(void) {
    int n = 10;
    increment(n);
    printf("%d\n", n);
    return 0;
}

exercises.starter_code:
#include <stdio.h>

void increment(int *x) {
    *x = *x + 1;
}

int main(void) {
    int n = 10;
    increment(&n);
    printf("%d\n", n);
    return 0;
}

