#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *values = malloc(10);
    int total = 0;
    for (int i = 0; i < 10; ++i) { values[i] = i; total += values[i]; }
    printf("%d\n", total);
    free(values);
    return 0;
}

exercises.starter_code:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *values = malloc(10 * sizeof(*values));
    int total = 0;
    for (int i = 0; i < 10; ++i) { values[i] = i; total += values[i]; }
    printf("%d\n", total);
    free(values);
    return 0;
}

